<?php
require_once __DIR__ . '/../includes/db.php'; require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $reviewId=(int)($_POST['review_id']??0); $delete=$pdo->prepare('DELETE FROM reviews WHERE review_id = ?'); $delete->execute([$reviewId]); set_flash('success','Review removed.'); redirect('admin/reviews.php'); }
$page_title='Manage Reviews'; $reviews=$pdo->query('SELECT r.*,i.item_name,u.name AS reviewer_name FROM reviews r INNER JOIN items i ON i.item_id=r.item_id INNER JOIN users u ON u.user_id=r.reviewer_id ORDER BY r.created_at DESC')->fetchAll(); require_once __DIR__ . '/../includes/header.php'; require __DIR__ . '/_nav.php';
?>
<h1 class="h3 mb-4">Reviews</h1><?php if (!$reviews): ?><div class="card shadow-sm"><div class="card-body text-center p-5"><p class="text-muted mb-0">No reviews found.</p></div></div><?php else: ?><div class="vstack gap-3"><?php foreach($reviews as $review): ?><div class="card shadow-sm"><div class="card-body"><div class="d-flex justify-content-between gap-3"><div><strong><?php echo e($review['item_name']); ?></strong><span class="text-brand ms-2"><?php echo str_repeat('*',(int)$review['rating']); ?></span><p class="small text-muted mb-2">By <?php echo e($review['reviewer_name']); ?> on <?php echo e(date('d M Y',strtotime($review['created_at']))); ?></p><p class="mb-0"><?php echo nl2br(e($review['review_text'])); ?></p></div><form method="post"><input type="hidden" name="review_id" value="<?php echo e($review['review_id']); ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Remove this review?">Remove</button></form></div></div></div><?php endforeach; ?></div><?php endif; ?><?php require_once __DIR__ . '/../includes/footer.php'; ?>
